namespace LE.SaveEditor.Services.GameData.Items;

/// <summary>Item bases and their implicits, read from <c>base.db</c> (generated by <c>LE.SaveEditor.DB</c>).</summary>
public interface IItemBaseCatalog
{
    /// <summary><c>true</c> when <c>base.db</c> exists and its item types could be read.</summary>
    bool IsAvailable { get; }

    /// <summary>
    /// <c>base.db</c> was generated before stat names were stored (no <c>Properties</c> table):
    /// implicits show as "Property 10" until the database is updated.
    /// </summary>
    bool IsOutdated { get; }

    /// <summary>Bases that fit <paramref name="slot"/>, ordered by level requirement then name.</summary>
    IReadOnlyList<ItemBase> GetBases(EquipmentSlot slot);

    /// <summary>Unique items (<paramref name="sets"/> = <c>false</c>) or set items that fit <paramref name="slot"/>.</summary>
    IReadOnlyList<ItemBase> GetUniques(EquipmentSlot slot, bool sets);

    /// <summary>Forgets what was read, so a database written by the generator is picked up.</summary>
    void ClearCache();
}
